package com.vandorlabs.neoforge.canopy;

import java.util.*;
import net.minecraft.core.BlockPos;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.item.ItemStack;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;

/** Actual Survival destroyBlock callbacks, with actual accepted item-spawn ownership records. */
@EventBusSubscriber(modid="vandorlabs")
final class CanopyHarvestHostChecks {
    static boolean refuseRemoval;
    static final class FaultBlock extends NativeCanopyBlock {FaultBlock(String kind,java.util.function.Supplier<? extends net.minecraft.world.level.block.entity.BlockEntityType<?>> type,net.minecraft.world.level.block.state.BlockBehaviour.Properties props){super(kind,type,props);}@Override protected boolean removeOwnedCell(ServerLevel world,BlockPos pos){return !refuseRemoval&&super.removeOwnedCell(world,pos);}}
    private static final List<ItemStack> DROPS=new ArrayList<>();
    @SubscribeEvent public static void spawn(net.neoforged.neoforge.event.entity.EntityJoinLevelEvent event){if(System.getProperty("vandorlabs.transmitterPhase","").startsWith("canopy-host-")&&System.getProperty("vandorlabs.transmitterPhase","").contains("harvest")&&!event.getLevel().isClientSide&&event.getEntity() instanceof net.minecraft.world.entity.item.ItemEntity item)DROPS.add(item.getItem().copy());}
    private static final BlockPos REFUSED_ROOT=new BlockPos(72,240,8),REFUSED_HELPER=REFUSED_ROOT.south();
    static void refusal(ServerLevel world){var tag=new net.minecraft.nbt.CompoundTag();tag.putString("OriginalPrivateCanopy","retained");tag.putLong("Anchor",com.vandorlabs.persistence.LegacyBlockPosition.pack(REFUSED_ROOT.getX(),REFUSED_ROOT.getY(),REFUSED_ROOT.getZ()));world.getChunkAt(REFUSED_ROOT);var root=CanopyHostChecks.put(world,REFUSED_ROOT,"long_canopy",net.minecraft.core.Direction.NORTH,tag);var cells=NativeCanopyFootprint.cells(root.kind(),REFUSED_ROOT,root.facing(),root.settings(),root.links());for(var cell:cells)if(!cell.equals(REFUSED_ROOT)){var helper=CanopyHostChecks.put(world,cell,root.kind(),root.facing(),new net.minecraft.nbt.CompoundTag());helper.helperOf(root);}refuseRemoval=true;try{if(!mine(world,REFUSED_ROOT).isEmpty())throw new AssertionError("Refused helper deletion duplicated item");}finally{refuseRemoval=false;}var owner=NativeCanopyLifecycle.at(world,REFUSED_HELPER);if(owner==null||!owner.inert()||!owner.recoverySnapshot().getString("OriginalPrivateCanopy").equals("retained"))throw new AssertionError("Refused removal lost original recovery owner");var remnant=NativeCanopyLifecycle.at(world,REFUSED_ROOT.south(2));if(remnant==null||remnant.initialized()||!NativeCanopyItem.pick(remnant.getBlockState().getBlock().asItem(),remnant).isEmpty())throw new AssertionError("Refused removal left extra drop owner");System.out.println("[vandorlabs][canopy-harvest] refused removal source0/drop0/recovery1/remnant0 PASS");}
    static void read(ServerLevel world){world.getChunkAt(REFUSED_HELPER);var root=NativeCanopyLifecycle.at(world,REFUSED_HELPER);if(root==null||!root.inert()||!root.recoverySnapshot().getString("OriginalPrivateCanopy").equals("retained"))throw new AssertionError("Refused removal recovery failed restart");var remnant=NativeCanopyLifecycle.at(world,REFUSED_ROOT.south(2));if(remnant==null||remnant.initialized()||!NativeCanopyItem.pick(remnant.getBlockState().getBlock().asItem(),remnant).isEmpty())throw new AssertionError("Refused removal remnant revived after restart");var loot=mine(world,REFUSED_HELPER);if(loot.size()!=1||loot.get(0).getCount()!=1||!loot.get(0).get(net.minecraft.core.component.DataComponents.CUSTOM_DATA).copyTag().getCompound(NativeCanopyEntity.RECOVERY).getString("OriginalPrivateCanopy").equals("retained"))throw new AssertionError("Refused removal does not mine to one complete original recovery envelope");System.out.println("[vandorlabs][canopy-harvest] refused removal restart/drop1/remnant0 PASS");}
    static List<ItemStack> mine(ServerLevel world,BlockPos pos){DROPS.clear();var player=new net.neoforged.neoforge.common.util.FakePlayer(world,new com.mojang.authlib.GameProfile(UUID.fromString("7d0d457b-dd72-49e1-b109-a20b0575a686"),"CanopyHarvest"));player.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);player.getInventory().selected=0;player.setPos(pos.getX()+.5,pos.getY()+1,pos.getZ()+2);player.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,ItemStack.EMPTY);if(!player.gameMode.destroyBlock(pos))throw new AssertionError("Actual Canopy Survival mining refused "+pos);return List.copyOf(DROPS);}
}
